namespace GymTrack.Services;

public sealed record ExerciseGuide(string Muscles, IReadOnlyList<string> Steps, string Caution);

public static class ExerciseGuideCatalog
{
    private static ExerciseGuide Guide(string muscles, string steps, string caution) =>
        new(muscles, steps.Split('|', StringSplitOptions.TrimEntries), caution);

    private static readonly IReadOnlyDictionary<string, ExerciseGuide> Guides =
        new Dictionary<string, ExerciseGuide>(StringComparer.Ordinal)
        {
            ["prancha frontal"] = Guide("Abdominais, glúteos e estabilizadores do tronco", "Apoie os antebraços abaixo dos ombros e estenda as pernas.|Contraia o abdômen e mantenha cabeça, tronco e quadris alinhados.|Respire normalmente durante o tempo previsto.", "Evite deixar a lombar afundar ou elevar demais o quadril."),
            ["abdominal no solo"] = Guide("Reto abdominal", "Deite-se de costas com joelhos flexionados e pés apoiados.|Eleve suavemente a parte superior do tronco, aproximando as costelas do quadril.|Retorne ao solo de forma controlada.", "Não puxe a cabeça nem use impulso com o pescoço."),
            ["flexao de punhos com halteres"] = Guide("Flexores do antebraço", "Apoie os antebraços e deixe os punhos livres na borda do apoio.|Flexione os punhos para elevar os halteres sem mover os cotovelos.|Desça lentamente até a amplitude confortável.", "Use carga leve o suficiente para manter o punho sob controle."),
            ["rosca direta com halteres"] = Guide("Bíceps braquial e braquial", "Fique em pé com um halter em cada mão e braços ao lado do corpo.|Flexione os cotovelos mantendo os braços próximos do tronco.|Desça os halteres devagar.", "Evite balançar o tronco para vencer a carga."),
            ["rosca martelo"] = Guide("Braquial, braquiorradial e bíceps", "Segure os halteres com as palmas voltadas uma para a outra.|Flexione os cotovelos sem afastá-los do tronco.|Volte à posição inicial com controle.", "Mantenha os punhos alinhados e não balance o corpo."),
            ["remada alta com halteres"] = Guide("Deltoides e trapézio", "Segure os halteres à frente do corpo com postura estável.|Puxe os cotovelos para cima até uma altura confortável.|Abaixe os halteres lentamente.", "Não force os ombros acima da amplitude confortável."),
            ["puxada frontal"] = Guide("Latíssimo do dorso, romboides e bíceps", "Ajuste o banco e segure a barra acima da cabeça.|Puxe a barra em direção à parte alta do peito, conduzindo os cotovelos para baixo.|Retorne os braços com controle.", "Evite puxar a barra atrás da cabeça ou jogar o tronco para trás."),
            ["remada curvada"] = Guide("Dorsais, romboides e bíceps", "Afaste os pés e incline o tronco a partir do quadril com a coluna neutra.|Puxe os pesos em direção à cintura, aproximando os cotovelos do tronco.|Estenda os braços novamente sem perder a postura.", "Não arredonde a lombar nem erga o tronco a cada repetição."),
            ["extensao lombar no banco"] = Guide("Eretores da coluna, glúteos e posteriores de coxa", "Ajuste o banco para permitir que o quadril se mova livremente.|Incline o tronco de forma controlada.|Volte até alinhar tronco e pernas.", "Evite hiperestender a coluna no topo do movimento."),
            ["desenvolvimento com halteres"] = Guide("Deltoides e tríceps", "Segure os halteres próximos à altura dos ombros.|Empurre os pesos acima da cabeça em trajetória confortável.|Desça até a altura inicial com controle.", "Mantenha o abdômen firme e evite arquear excessivamente a lombar."),
            ["elevacao lateral"] = Guide("Deltoide lateral", "Segure os halteres ao lado do corpo com cotovelos levemente flexionados.|Eleve os braços lateralmente até perto da altura dos ombros.|Abaixe devagar, sem deixar os pesos cair.", "Evite encolher os ombros e usar impulso."),
            ["supino reto com halteres"] = Guide("Peitoral maior, deltoide anterior e tríceps", "Deite-se no banco com os pés firmes no chão e halteres acima do peito.|Desça os pesos de forma controlada ao lado do tronco.|Empurre até retornar acima do peito.", "Mantenha os punhos alinhados e não perca o contato estável com o banco."),
            ["supino inclinado com halteres"] = Guide("Peitoral superior, deltoide anterior e tríceps", "Ajuste o banco em inclinação moderada e apoie os pés.|Desça os halteres ao lado da parte alta do peito.|Empurre para cima de modo controlado.", "Evite bater os halteres entre si ou arquear demais a lombar."),
            ["crucifixo com halteres"] = Guide("Peitoral maior e deltoide anterior", "Deite-se no banco com halteres acima do peito e cotovelos levemente flexionados.|Abra os braços em arco até uma amplitude confortável.|Feche os braços pelo mesmo arco.", "Não deixe os ombros descerem além da amplitude confortável."),
            ["flexao de bracos"] = Guide("Peitoral maior, tríceps e deltoide anterior", "Apoie mãos abaixo ou ligeiramente fora da linha dos ombros e alinhe o corpo.|Flexione os cotovelos e aproxime o peito do chão.|Empurre o chão até retornar ao início.", "Evite deixar o quadril cair ou abrir excessivamente os cotovelos."),
            ["mobilidade cervical"] = Guide("Músculos do pescoço", "Sente-se ou fique em pé com a coluna confortável.|Mova a cabeça lentamente em uma direção de cada vez.|Retorne ao centro antes de mudar de direção.", "Não force o fim da amplitude nem continue se houver dor ou tontura."),
            ["encolhimento com halteres"] = Guide("Trapézio superior", "Segure os halteres ao lado do corpo com braços estendidos.|Eleve os ombros em direção às orelhas.|Abaixe-os lentamente.", "Não gire os ombros nem use balanço do corpo."),
            ["triceps na polia"] = Guide("Tríceps braquial", "Ajuste a polia alta e mantenha os cotovelos próximos do tronco.|Estenda os braços para baixo sem mover os ombros.|Retorne os antebraços com controle.", "Evite projetar o tronco sobre o peso."),
            ["triceps frances"] = Guide("Tríceps braquial", "Segure o peso acima da cabeça com cotovelos apontados para cima.|Flexione os cotovelos e desça o peso atrás da cabeça.|Estenda os braços de forma controlada.", "Use uma carga que permita manter os cotovelos estáveis."),
            ["cadeira abdutora"] = Guide("Glúteo médio e abdutores do quadril", "Ajuste o banco e apoie as pernas nos suportes.|Afaste as coxas contra a resistência.|Volte lentamente sem deixar o peso bater.", "Mantenha o tronco estável e evite usar impulso."),
            ["cadeira adutora"] = Guide("Adutores da coxa", "Ajuste o banco e posicione as pernas nos suportes.|Aproxime as coxas de forma controlada.|Retorne lentamente até uma abertura confortável.", "Não force a abertura das pernas além do confortável."),
            ["elevacao pelvica"] = Guide("Glúteo máximo e posteriores de coxa", "Apoie a parte alta das costas no banco e firme os pés no chão.|Eleve o quadril até alinhar tronco e coxas.|Desça o quadril com controle.", "Evite compensar o movimento hiperestendendo a lombar."),
            ["agachamento sumo"] = Guide("Quadríceps, glúteos e adutores", "Afaste os pés em base confortável, com pontas ligeiramente abertas.|Flexione quadris e joelhos mantendo os pés apoiados.|Empurre o chão e retorne à posição em pé.", "Deixe os joelhos acompanharem a direção dos pés, sem forçar a abertura."),
            ["coice no cabo"] = Guide("Glúteo máximo", "Prenda a tornozeleira ao cabo baixo e apoie-se para manter o equilíbrio.|Estenda o quadril levando a perna para trás sem girar o tronco.|Retorne lentamente.", "Evite arquear a lombar ou usar impulso."),
            ["elevacao de panturrilhas em pe"] = Guide("Gastrocnêmio e sóleo", "Fique em pé com os pés apoiados e use um suporte para equilíbrio se necessário.|Eleve os calcanhares até ficar na ponta dos pés.|Desça de forma lenta e controlada.", "Evite saltar ou deixar os tornozelos perderem o alinhamento."),
            ["mesa flexora"] = Guide("Posteriores de coxa", "Ajuste a máquina para alinhar os joelhos ao eixo e o apoio próximo aos tornozelos.|De barriga para baixo, flexione os joelhos aproximando os calcanhares dos glúteos.|Retorne as pernas lentamente.", "Mantenha o quadril apoiado no banco e evite levantar a lombar."),
            ["levantamento terra romeno"] = Guide("Posteriores de coxa, glúteos e eretores da coluna", "Segure os pesos junto ao corpo com joelhos levemente flexionados.|Leve os quadris para trás, inclinando o tronco com coluna neutra.|Estenda o quadril para voltar a ficar em pé.", "Mantenha os pesos próximos das pernas e não arredonde a coluna."),
            ["agachamento livre"] = Guide("Quadríceps, glúteos e posteriores de coxa", "Posicione os pés em uma base confortável e firme-os no chão.|Flexione quadris e joelhos de maneira controlada.|Desça mantendo equilíbrio e postura estável.|Empurre o chão para retornar à posição em pé.", "Mantenha os joelhos acompanhando a direção dos pés e use amplitude que permita controle."),
            ["leg press"] = Guide("Quadríceps, glúteos e posteriores de coxa", "Ajuste o banco e apoie toda a planta dos pés na plataforma.|Flexione os joelhos de forma controlada sem tirar o quadril do encosto.|Empurre a plataforma até retornar à posição inicial.", "Não trave os joelhos nem deixe a lombar perder contato com o banco."),
            ["cadeira extensora"] = Guide("Quadríceps", "Ajuste o banco e alinhe os joelhos ao eixo da máquina.|Estenda os joelhos de forma controlada.|Retorne lentamente sem soltar o peso.", "Evite impulsos e use amplitude confortável para os joelhos."),
            ["caminhada na esteira"] = Guide("Pernas e sistema cardiorrespiratório", "Inicie a esteira em velocidade confortável.|Caminhe com postura ereta e passadas naturais.|Reduza a velocidade antes de parar.", "Use os apoios para entrar e sair da esteira com segurança."),
            ["polichinelo"] = Guide("Corpo inteiro, especialmente pernas e ombros", "Fique em pé com braços ao lado do corpo.|Salte abrindo as pernas e elevando os braços.|Salte novamente para retornar ao centro.", "Adapte o impacto e o ritmo à sua capacidade; pare se perder o equilíbrio."),
            ["alongamento geral"] = Guide("Varia conforme a região alongada", "Escolha uma região e assuma uma posição estável.|Mova-se lentamente até sentir alongamento confortável.|Mantenha a posição sem prender a respiração e troque de lado.", "Evite movimentos bruscos ou posições dolorosas.")
        };

    public static ExerciseGuide? ForExercise(string name) =>
        Guides.TryGetValue(ExerciseMediaCatalog.Normalize(name), out var guide) ? guide : null;
}
